1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_main.c
3	 *
4	 * Xiaozhi AI Voice App — Phase 2 entry point.
5	 *
6	 * Full dialog: OTA -> wss connect -> hello -> listen start -> mic capture
7	 * (Opus uplink) -> listen stop -> receive stt/tts -> TTS Opus playback.
8	 *
9	 * SPDX-License-Identifier: Apache-2.0
10	 ****************************************************************************/
11	
12	#include <nuttx/config.h>
13	
14	#include <stdio.h>
15	#include <string.h>
16	#include <stdlib.h>
17	#include <unistd.h>
18	#include <pthread.h>
19	#include <semaphore.h>
20	
21	#include <netutils/cJSON.h>
22	
23	#include "xiaozhi_ota.h"
24	#include "xiaozhi_ws.h"
25	#include "xiaozhi_audio.h"
26	#include "xiaozhi_mcp.h"
27	
28	/****************************************************************************
29	 * Pre-processor Definitions
30	 ****************************************************************************/
31	
32	#define XIAOZHI_MAC_DEFAULT "6b:48:a8:95:7d:e1"
33	#define XZ_OPUS_MAX        400
34	#define XZ_DIALOG_SECONDS  4      /* capture duration per turn */
35	
36	/****************************************************************************
37	 * Private Types
38	 ****************************************************************************/
39	
40	struct xiaozhi_app_s
41	{
42	  struct xiaozhi_ws_s    ws;
43	  struct xiaozhi_audio_s audio;
44	  char session_id[16];
45	  bool ws_connected;
46	  bool got_stt;
47	  bool tts_playing;
48	  int  tts_sentences;
49	};
50	
51	/* Context shared with the uplink worker thread. */
52	struct uplink_ctx_s
53	{
54	  struct xiaozhi_app_s *app;
55	  int seconds;
56	};
57	
58	/****************************************************************************
59	 * Private Data
60	 ****************************************************************************/
61	
62	static struct xiaozhi_app_s g_app;
63	
64	/****************************************************************************
65	 * Private Functions
66	 ****************************************************************************/
67	
68	/* Send a JSON text frame built with cJSON. */
69	static int send_json(struct xiaozhi_app_s *app, cJSON *root)
70	{
71	  char *json = cJSON_PrintUnformatted(root);
72	  if (json == NULL)
73	    {
74	      return -ENOMEM;
75	    }
76	
77	  int ret = xiaozhi_ws_send_text(&app->ws, json, strlen(json));
78	  free(json);
79	  return ret;
80	}
81	
82	/* Uplink worker: capture Opus frames and send as binary frames for the
83	 * given number of seconds.
84	 */
85	static void *uplink_worker(void *arg)
86	{
87	  struct uplink_ctx_s *uc = arg;
88	  struct xiaozhi_app_s *app = uc->app;
89	  uint8_t frame[XZ_OPUS_MAX];
90	  int frames = 0;
91	  int target_frames = (uc->seconds * 1000) / 60;   /* 60ms per frame */
92	
93	  printf("[xiaozhi] uplink: capturing %d frames (%ds)\n",
94	         target_frames, uc->seconds);
95	
96	  while (frames < target_frames && app->ws_connected)
97	    {
98	      ssize_t n = xiaozhi_audio_read_opus(&app->audio, frame, sizeof(frame));
99	      if (n < 0)
100	        {
101	          printf("[xiaozhi] uplink read err: %zd\n", n);
102	          break;
103	        }
104	
105	      if (n > 0)
106	        {
107	          int ret = xiaozhi_ws_send_binary(&app->ws, frame, n);
108	          if (ret != 0)
109	            {
110	              printf("[xiaozhi] uplink send err: %d\n", ret);
111	              break;
112	            }
113	
114	          frames++;
115	        }
116	    }
117	
118	  printf("[xiaozhi] uplink: sent %d/%d frames\n", frames, target_frames);
119	  return NULL;
120	}
121	
122	/* Receive worker: parse server messages and feed TTS audio to the player.
123	 * Runs until ws is closed or a stop condition.
124	 */
125	static void recv_loop(struct xiaozhi_app_s *app, int max_ms)
126	{
127	  int waited = 0;
128	
129	  while (app->ws_connected && waited < max_ms)
130	    {
131	      const uint8_t *payload;
132	      size_t plen;
133	      bool is_binary;
134	      int ret;
135	
136	      ret = xiaozhi_ws_recv(&app->ws, &payload, &plen, &is_binary);
137	      if (ret != 0)
138	        {
139	          app->ws_connected = false;
140	          break;
141	        }
142	
143	      if (is_binary)
144	        {
145	          /* Server TTS Opus frame -> feed to player. */
146	          if (app->tts_playing)
147	            {
148	              int wret = xiaozhi_audio_write_opus(&app->audio,
149	                                                  payload, plen);
150	              if (wret < 0)
151	                {
152	                  printf("[xiaozhi] TTS write failed (%d), "
153	                         "stopping playback\n", wret);
154	                  app->tts_playing = false;
155	                  xiaozhi_audio_stop_playback(&app->audio);
156	                  break;
157	                }
158	            }
159	
160	          waited += 60;
161	          continue;
162	        }
163	
164	      /* Text frame: parse JSON. */
165	      {
166	        char *json = malloc(plen + 1);
167	        if (json == NULL)
168	          {
169	            continue;
170	          }
171	
172	        memcpy(json, payload, plen);
173	        json[plen] = '\0';
174	
175	        cJSON *root = cJSON_Parse(json);
176	        if (root != NULL)
177	          {
178	            cJSON *type = cJSON_GetObjectItem(root, "type");
179	            const char *tstr = cJSON_IsString(type) ?
180	              type->valuestring : "";
181	
182	            if (strcmp(tstr, "stt") == 0)
183	              {
184	                cJSON *text = cJSON_GetObjectItem(root, "text");
185	                printf("[xiaozhi] <<< STT: \"%s\"\n",
186	                       text ? text->valuestring : "?");
187	                app->got_stt = true;
188	              }
189	            else if (strcmp(tstr, "llm") == 0)
190	              {
191	                cJSON *text = cJSON_GetObjectItem(root, "text");
192	                printf("[xiaozhi] <<< LLM: \"%s\" (%s)\n",
193	                       text ? text->valuestring : "?",
194	                       cJSON_IsString(cJSON_GetObjectItem(root, "emotion")) ?
195	                       cJSON_GetObjectItem(root, "emotion")->valuestring :
196	                       "-");
197	              }
198	            else if (strcmp(tstr, "mcp") == 0)
199	              {
200	                cJSON *payload = cJSON_GetObjectItem(root, "payload");
201	                if (cJSON_IsObject(payload))
202	                  {
203	                    xiaozhi_mcp_handle_message(&app->ws,
204	                                               app->session_id, payload);
205	                  }
206	              }
207	            else if (strcmp(tstr, "tts") == 0)
208	              {
209	                cJSON *state = cJSON_GetObjectItem(root, "state");
210	                const char *sstr = cJSON_IsString(state) ?
211	                  state->valuestring : "";
212	
213	                if (strcmp(sstr, "start") == 0)
214	                  {
215	                    int pret = xiaozhi_audio_start_playback(&app->audio);
216	                    if (pret == 0)
217	                      {
218	                        app->tts_playing = true;
219	                      }
220	
221	                    printf("[xiaozhi] <<< TTS start (player=%s)\n",
222	                           pret == 0 ? "ok" : "failed");
223	                  }
224	                else if (strcmp(sstr, "stop") == 0)
225	                  {
226	                    app->tts_playing = false;
227	                    printf("[xiaozhi] <<< TTS stop\n");
228	                    xiaozhi_audio_stop_playback(&app->audio);
229	                    break;   /* end of this turn */
230	                  }
231	                else if (strcmp(sstr, "sentence_start") == 0)
232	                  {
233	                    cJSON *text = cJSON_GetObjectItem(root, "text");
234	                    printf("[xiaozhi] <<< TTS: \"%s\"\n",
235	                           text ? text->valuestring : "?");
236	                    app->tts_sentences++;
237	                  }
238	              }
239	            else if (strcmp(tstr, "goodbye") == 0)
240	              {
241	                printf("[xiaozhi] <<< goodbye\n");
242	                app->ws_connected = false;
243	                cJSON_Delete(root);
244	                free(json);
245	                break;
246	              }
247	            else if (strcmp(tstr, "hello") == 0)
248	              {
249	                cJSON *sid = cJSON_GetObjectItem(root, "session_id");
250	                if (cJSON_IsString(sid))
251	                  {
252	                    strncpy(app->session_id, sid->valuestring,
253	                            sizeof(app->session_id) - 1);
254	                    printf("[xiaozhi] <<< hello: session_id=%s\n",
255	                           app->session_id);
256	                  }
257	              }
258	            else
259	              {
260	                printf("[xiaozhi] <<< %s\n", tstr);
261	              }
262	
263	            cJSON_Delete(root);
264	          }
265	        else
266	          {
267	            printf("[xiaozhi] <<< (parse err) %.*s\n",
268	                   (int)plen, (const char *)payload);
269	          }
270	
271	        free(json);
272	      }
273	
274	      waited += 60;
275	    }
276	}
