278	/****************************************************************************
279	 * Public Functions
280	 ****************************************************************************/
281	
282	int main(int argc, FAR char *argv[])
283	{
284	  struct xiaozhi_ota_config_s ota;
285	  const char *mac = XIAOZHI_MAC_DEFAULT;
286	  char client_id[40];
287	  int ret;
288	  struct uplink_ctx_s uc;
289	
290	  memset(&g_app, 0, sizeof(g_app));
291	
292	  printf("[xiaozhi] === Phase 2: full dialog ===\n");
293	
294	  snprintf(client_id, sizeof(client_id),
295	           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);
296	
297	  /* Init audio subsystem. */
298	  ret = xiaozhi_audio_init(&g_app.audio);
299	  if (ret != 0)
300	    {
301	      printf("[xiaozhi] audio init failed: %d\n", ret);
302	      return 1;
303	    }
304	
305	  /* Step 1: OTA. */
306	  printf("[xiaozhi] step 1: OTA\n");
307	  ret = xiaozhi_ota_fetch(mac, &ota);
308	  if (ret != 0)
309	    {
310	      printf("[xiaozhi] OTA failed: %d\n", ret);
311	      return 1;
312	    }
313	
314	  /* Step 2: wss connect + hello. */
315	  printf("[xiaozhi] step 2: wss connect\n");
316	  ret = xiaozhi_ws_connect(&g_app.ws, ota.ws_url, ota.ws_token, mac,
317	                           client_id);
318	  if (ret != 0)
319	    {
320	      printf("[xiaozhi] ws connect failed: %d\n", ret);
321	      return 1;
322	    }
323	
324	  g_app.ws_connected = true;
325	
326	  /* Wait for hello response to get session_id. */
327	  printf("[xiaozhi] step 3: wait hello\n");
328	  recv_loop(&g_app, 5000);   /* up to 5s for hello */
329	  if (g_app.session_id[0] == '\0')
330	    {
331	      printf("[xiaozhi] no session_id, abort\n");
332	      goto out;
333	    }
334	
335	  /* Announce device capabilities (notably MCP) to the cloud with a device
336	   * hello. The cloud starts an MCP session only after seeing features.mcp.
337	   */
338	  {
339	    cJSON *hello       = cJSON_CreateObject();
340	    cJSON *features    = cJSON_CreateObject();
341	    cJSON *audio_params = cJSON_CreateObject();
342	
343	    cJSON_AddStringToObject(hello, "type", "hello");
344	    cJSON_AddNumberToObject(hello, "version", 1);
345	    cJSON_AddStringToObject(hello, "transport", "websocket");
346	    cJSON_AddItemToObject(hello, "features", features);
347	    xiaozhi_mcp_add_features(features);
348	    cJSON_AddItemToObject(hello, "audio_params", audio_params);
349	    cJSON_AddStringToObject(audio_params, "format", "opus");
350	    cJSON_AddNumberToObject(audio_params, "sample_rate", 16000);
351	    cJSON_AddNumberToObject(audio_params, "channels", 1);
352	
353	    send_json(&g_app, hello);
354	    cJSON_Delete(hello);
355	    printf("[xiaozhi] >>> hello (features.mcp=true)\n");
356	  }
357	
358	  /* Step 4: listen start + capture + listen stop. */
359	  printf("[xiaozhi] step 4: listen start + capture\n");
360	  {
361	    cJSON *hello = cJSON_CreateObject();
362	    cJSON_AddStringToObject(hello, "session_id", g_app.session_id);
363	    cJSON_AddStringToObject(hello, "type", "listen");
364	    cJSON_AddStringToObject(hello, "state", "start");
365	    cJSON_AddStringToObject(hello, "mode", "manual");
366	    send_json(&g_app, hello);
367	    cJSON_Delete(hello);
368	    printf("[xiaozhi] >>> listen start\n");
369	  }
370	
371	  /* Start capture and run uplink worker for N seconds. */
372	  ret = xiaozhi_audio_start_capture(&g_app.audio);
373	  if (ret != 0)
374	    {
375	      printf("[xiaozhi] capture start failed: %d\n", ret);
376	      goto out;
377	    }
378	
379	  /* Drain any incoming binary/text while capturing by spawning uplink in
380	   * a thread and looping recv here too. Simplest: run uplink synchronously
381	   * (block on capture), the server tolerates a gap before listen stop.
382	   */
383	  uc.app = &g_app;
384	  uc.seconds = XZ_DIALOG_SECONDS;
385	  uplink_worker(&uc);
386	
387	  xiaozhi_audio_stop_capture(&g_app.audio);
388	
389	  /* listen stop. */
390	  {
391	    cJSON *stop = cJSON_CreateObject();
392	    cJSON_AddStringToObject(stop, "session_id", g_app.session_id);
393	    cJSON_AddStringToObject(stop, "type", "listen");
394	    cJSON_AddStringToObject(stop, "state", "stop");
395	    send_json(&g_app, stop);
396	    cJSON_Delete(stop);
397	    printf("[xiaozhi] >>> listen stop\n");
398	  }
399	
400	  /* Step 5: receive stt + tts + playback (up to 20s). */
401	  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
402	  recv_loop(&g_app, 20000);
403	
404	out:
405	  if (g_app.tts_playing)
406	    {
407	      xiaozhi_audio_stop_playback(&g_app.audio);
408	    }
409	
410	  xiaozhi_audio_deinit(&g_app.audio);
411	  xiaozhi_ws_close(&g_app.ws);
412	
413	  printf("[xiaozhi] === done: stt=%s tts=%d ===\n",
414	         g_app.got_stt ? "yes" : "no", g_app.tts_sentences);
415	  return 0;
416	}
