1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_ws.c
3	 *
4	 * A lightweight WebSocket-over-TLS (wss) client.
5	 *   - TLS layer: mbedtls (pattern borrowed from packages/demos/mimo)
6	 *   - WebSocket framing: RFC 6455
7	 *
8	 * Supports the subset needed by the xiaozhi protocol:
9	 *   - client->server text(0x1) and binary(0x2) frames, masked
10	 *   - server->client text/binary/close frames, unmasked
11	 *   - payload lengths up to 65535 (16-bit length); 64-bit length not needed
12	 *     here (Opus frames and JSON messages are short)
13	 *
14	 * SPDX-License-Identifier: Apache-2.0
15	 ****************************************************************************/
16	
17	#include <nuttx/config.h>
18	
19	#include <stdio.h>
20	#include <string.h>
21	#include <stdlib.h>
22	#include <errno.h>
23	#include <unistd.h>
24	#include <netdb.h>
25	#include <netinet/in.h>
26	#include <arpa/inet.h>
27	#include <sys/socket.h>
28	
29	#include "xiaozhi_ws.h"
30	
31	/****************************************************************************
32	 * Pre-processor Definitions
33	 ****************************************************************************/
34	
35	#define WS_RXBUF_SIZE  4096
36	
37	/* WebSocket opcodes */
38	#define WS_OPCODE_CONTINUATION 0x0
39	#define WS_OPCODE_TEXT         0x1
40	#define WS_OPCODE_BINARY       0x2
41	#define WS_OPCODE_CLOSE        0x8
42	#define WS_OPCODE_PING         0x9
43	#define WS_OPCODE_PONG         0xa
44	
45	#define WS_FIN_BIT   0x80
46	#define WS_MASK_BIT  0x80
47	
48	/****************************************************************************
49	 * Private Functions - TLS
50	 ****************************************************************************/
51	
52	/* BIO send: write to the plain TCP fd. */
53	static int ws_bio_send(void *ctx, const unsigned char *buf, size_t len)
54	{
55	  int fd = *(int *)ctx;
56	  ssize_t ret = send(fd, buf, len, 0);
57	  if (ret < 0)
58	    {
59	      return -EIO;
60	    }
61	
62	  return (int)ret;
63	}
64	
65	/* BIO recv: read from the plain TCP fd. */
66	static int ws_bio_recv(void *ctx, unsigned char *buf, size_t len)
67	{
68	  int fd = *(int *)ctx;
69	  ssize_t ret = recv(fd, buf, len, 0);
70	  if (ret < 0)
71	    {
72	      return -EIO;
73	    }
74	
75	  if (ret == 0)
76	    {
77	      return MBEDTLS_ERR_SSL_WANT_READ;
78	    }
79	
80	  return (int)ret;
81	}
82	
83	static int ws_tls_init(struct xiaozhi_ws_s *ws)
84	{
85	  int ret;
86	
87	  mbedtls_ssl_init(&ws->ssl);
88	  mbedtls_ssl_config_init(&ws->conf);
89	  mbedtls_entropy_init(&ws->entropy);
90	  mbedtls_ctr_drbg_init(&ws->ctr_drbg);
91	
92	  ret = mbedtls_ctr_drbg_seed(&ws->ctr_drbg, mbedtls_entropy_func,
93	                              &ws->entropy,
94	                              (const unsigned char *)"xiaozhi", 7);
95	  if (ret != 0)
96	    {
97	      printf("[xiaozhi] drbg seed failed: -0x%x\n", -ret);
98	      return -EIO;
99	    }
100	
101	  ret = mbedtls_ssl_config_defaults(&ws->conf, MBEDTLS_SSL_IS_CLIENT,
102	                                    MBEDTLS_SSL_TRANSPORT_STREAM,
103	                                    MBEDTLS_SSL_PRESET_DEFAULT);
104	  if (ret != 0)
105	    {
106	      printf("[xiaozhi] ssl config defaults failed: -0x%x\n", -ret);
107	      return -EIO;
108	    }
109	
110	  /* Skip server cert verification for embedded use.
111	   * For production, configure CA certs via mbedtls_ssl_conf_ca_chain().
112	   */
113	  mbedtls_ssl_conf_authmode(&ws->conf, MBEDTLS_SSL_VERIFY_NONE);
114	  mbedtls_ssl_conf_rng(&ws->conf, mbedtls_ctr_drbg_random, &ws->ctr_drbg);
115	
116	  ret = mbedtls_ssl_setup(&ws->ssl, &ws->conf);
117	  if (ret != 0)
118	    {
119	      printf("[xiaozhi] ssl setup failed: -0x%x\n", -ret);
120	      return -EIO;
121	    }
122	
123	  return 0;
124	}
125	
126	/* Connect TCP, do TLS handshake over it. */
127	static int ws_tls_connect(struct xiaozhi_ws_s *ws, const char *host,
128	                         const char *port)
129	{
130	  struct hostent *he;
131	  struct sockaddr_in server;
132	  int portnum = atoi(port);
133	  int ret;
134	
135	  printf("[xiaozhi] TLS connecting to %s:%s\n", host, port);
136	
137	  he = gethostbyname(host);
138	  if (he == NULL)
139	    {
140	      printf("[xiaozhi] DNS resolve failed for %s\n", host);
141	      return -EIO;
142	    }
143	
144	  ws->fd = socket(AF_INET, SOCK_STREAM, 0);
145	  if (ws->fd < 0)
146	    {
147	      printf("[xiaozhi] socket() failed: %d\n", errno);
148	      return -EIO;
149	    }
150	
151	  memset(&server, 0, sizeof(server));
152	  server.sin_family = AF_INET;
153	  server.sin_port   = htons(portnum);
154	  memcpy(&server.sin_addr, he->h_addr_list[0], he->h_length);
155	
156	  printf("[xiaozhi] TCP connect to %s:%d\n",
157	         inet_ntoa(server.sin_addr), portnum);
158	
159	  if (connect(ws->fd, (struct sockaddr *)&server, sizeof(server)) < 0)
160	    {
161	      printf("[xiaozhi] TCP connect failed: %d\n", errno);
162	      close(ws->fd);
163	      ws->fd = -1;
164	      return -EIO;
165	    }
166	
167	  printf("[xiaozhi] TCP connected, starting TLS handshake\n");
168	
169	  ret = mbedtls_ssl_set_hostname(&ws->ssl, host);
170	  if (ret != 0)
171	    {
172	      printf("[xiaozhi] set hostname failed: -0x%x\n", -ret);
173	      goto err;
174	    }
175	
176	  mbedtls_ssl_set_bio(&ws->ssl, &ws->fd, ws_bio_send, ws_bio_recv, NULL);
177	
178	  while ((ret = mbedtls_ssl_handshake(&ws->ssl)) != 0)
179	    {
180	      if (ret != MBEDTLS_ERR_SSL_WANT_READ &&
181	          ret != MBEDTLS_ERR_SSL_WANT_WRITE)
182	        {
183	          printf("[xiaozhi] TLS handshake failed: -0x%x\n", -ret);
184	          goto err;
185	        }
186	    }
187	
188	  printf("[xiaozhi] TLS handshake complete\n");
189	  return 0;
190	
191	err:
192	  close(ws->fd);
193	  ws->fd = -1;
194	  return -EIO;
195	}
196	
197	/****************************************************************************
198	 * Private Functions - TLS read/write wrappers
199	 ****************************************************************************/
200	
201	/* Send all bytes over TLS. Returns 0 on success, -errno on failure. */
202	static int ws_tls_write_all(struct xiaozhi_ws_s *ws,
203	                            const uint8_t *buf, size_t len)
204	{
205	  size_t written = 0;
206	  while (written < len)
207	    {
208	      int ret = mbedtls_ssl_write(&ws->ssl, buf + written, len - written);
209	      if (ret == MBEDTLS_ERR_SSL_WANT_WRITE ||
210	          ret == MBEDTLS_ERR_SSL_WANT_READ)
211	        {
212	          continue;
213	        }
214	
215	      if (ret <= 0)
216	        {
217	          printf("[xiaozhi] tls write error: -0x%x\n", -ret);
218	          return -EIO;
219	        }
220	
221	      written += ret;
222	    }
223	
224	  return 0;
225	}
226	
227	/* Read exactly n bytes over TLS into buf. Returns 0 on success, -errno. */
228	static int ws_tls_read_all(struct xiaozhi_ws_s *ws, uint8_t *buf, size_t n)
229	{
230	  size_t got = 0;
231	  while (got < n)
232	    {
233	      int ret = mbedtls_ssl_read(&ws->ssl, buf + got, n - got);
234	      if (ret == MBEDTLS_ERR_SSL_WANT_READ ||
235	          ret == MBEDTLS_ERR_SSL_WANT_WRITE)
236	        {
237	          continue;
238	        }
239	
240	      if (ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY || ret == 0)
241	        {
242	          printf("[xiaozhi] tls peer closed during read\n");
243	          return -ECONNRESET;
244	        }
245	
246	      if (ret < 0)
247	        {
248	          printf("[xiaozhi] tls read error: -0x%x\n", -ret);
249	          return -EIO;
250	        }
251	
252	      got += ret;
253	    }
254	
255	  return 0;
256	}
257	
258	/****************************************************************************
259	 * Private Functions - WebSocket framing
260	 ****************************************************************************/
261	
262	/* Generate a random 4-byte masking key. mbedtls_ctr_drbg_random is used as
263	 * a random source (no Date.now/random needed).
264	 */
265	static void ws_make_mask(uint8_t mask[4], struct xiaozhi_ws_s *ws)
266	{
267	  mbedtls_ctr_drbg_random(&ws->ctr_drbg, mask, 4);
268	}
269	
270	/* Send one client->server frame (masked). */
271	static int ws_send_frame(struct xiaozhi_ws_s *ws, uint8_t opcode,
272	                         const uint8_t *data, size_t len)
273	{
274	  uint8_t hdr[14];
275	  size_t hdrlen;
276	  uint8_t mask[4];
277	  int ret;
278	
279	  hdr[0] = WS_FIN_BIT | opcode;
280	
281	  if (len <= 125)
282	    {
283	      hdr[1] = WS_MASK_BIT | (uint8_t)len;
284	      hdrlen = 2;
285	    }
286	  else if (len <= 65535)
287	    {
288	      hdr[1] = WS_MASK_BIT | 126;
289	      hdr[2] = (len >> 8) & 0xff;
290	      hdr[3] = len & 0xff;
291	      hdrlen = 4;
292	    }
293	  else
294	    {
295	      /* 64-bit length path. Opus/JSON frames are never this large, but
296	       * implement for completeness.
297	       */
298	      hdr[1] = WS_MASK_BIT | 127;
299	      uint64_t l = len;
300	      hdr[2] = 0; hdr[3] = 0; hdr[4] = 0; hdr[5] = 0;
301	      hdr[6] = (l >> 24) & 0xff;
302	      hdr[7] = (l >> 16) & 0xff;
303	      hdr[8] = (l >> 8) & 0xff;
304	      hdr[9] = l & 0xff;
305	      hdrlen = 10;
306	    }
307	
308	  ret = ws_tls_write_all(ws, hdr, hdrlen);
309	  if (ret != 0)
310	    {
311	      return ret;
312	    }
313	
314	  /* Masking key + masked payload. */
315	  ws_make_mask(mask, ws);
316	  ret = ws_tls_write_all(ws, mask, 4);
317	  if (ret != 0)
318	    {
319	      return ret;
320	    }
321	
322	  if (len > 0)
323	    {
324	      /* XOR the payload in a stack buffer to keep rxbuf/data const.
325	       * For large frames a streaming XOR would be better; xiaozhi payloads
326	       * are small (Opus <= ~400B, JSON <= ~2KB).
327	       */
328	      uint8_t masked[1];
329	      for (size_t i = 0; i < len; i++)
330	        {
331	          masked[0] = data[i] ^ mask[i & 3];
332	          ret = ws_tls_write_all(ws, masked, 1);
333	          if (ret != 0)
334	            {
335	              return ret;
336	            }
337	        }
338	    }
339	
340	  return 0;
341	}
342	
343	/****************************************************************************
344	 * Public Functions
345	 ****************************************************************************/
346	
347	int xiaozhi_ws_connect(struct xiaozhi_ws_s *ws, const char *ws_url,
348	                       const char *token, const char *device_id,
349	                       const char *client_id)
350	{
351	  char host[128];
352	  char path[256];
353	  char portstr[8];
354	  const char *p;
355	  const char *hoststart;
356	  const char *hostend;
357	  const char *pathstart;
358	  int port = 443;
359	  int ret;
360	  uint8_t wskey[16];
361	  char req[768];
362	
363	  memset(ws, 0, sizeof(*ws));
364	  ws->fd = -1;
365	
366	  /* Parse "wss://host[:port]/path..." */
367	  if (strncmp(ws_url, "wss://", 6) != 0)
368	    {
369	      printf("[xiaozhi] ws url must be wss://: %s\n", ws_url);
370	      return -EINVAL;
371	    }
372	
373	  hoststart = ws_url + 6;
374	  pathstart = strchr(hoststart, '/');
375	  hostend   = pathstart ? pathstart : hoststart + strlen(hoststart);
376	
377	  /* Detect port in host portion */
378	  p = memchr(hoststart, ':', hostend - hoststart);
379	  if (p != NULL)
380	    {
381	      size_t hlen = p - hoststart;
382	      memcpy(host, hoststart, hlen);
383	      host[hlen] = '\0';
384	      port = atoi(p + 1);
385	    }
386	  else
387	    {
388	      size_t hlen = hostend - hoststart;
389	      memcpy(host, hoststart, hlen);
390	      host[hlen] = '\0';
391	    }
392	
393	  snprintf(portstr, sizeof(portstr), "%d", port);
394	
395	  if (pathstart)
396	    {
397	      snprintf(path, sizeof(path), "%s", pathstart);
398	    }
399	  else
400	    {
401	      path[0] = '/'; path[1] = '\0';
402	    }
403	
404	  printf("[xiaozhi] ws host=%s port=%d path=%s token=%s\n",
405	         host, port, path, token);
406	
407	  /* Allocate rx buffer. */
408	  ws->rxbuf_cap = WS_RXBUF_SIZE;
409	  ws->rxbuf = malloc(ws->rxbuf_cap);
410	  if (ws->rxbuf == NULL)
411	    {
412	      return -ENOMEM;
413	    }
414	
415	  /* TLS init + connect. */
416	  ret = ws_tls_init(ws);
417	  if (ret != 0)
418	    {
419	      return ret;
420	    }
421	
422	  ret = ws_tls_connect(ws, host, portstr);
423	  if (ret != 0)
424	    {
425	      return ret;
426	    }
427	
428	  /* WebSocket HTTP Upgrade handshake. */
429	  mbedtls_ctr_drbg_random(&ws->ctr_drbg, wskey, 16);
430	
431	  /* Build Sec-WebSocket-Key (base64 of 16 random bytes). We use a tiny
432	   * base64 encoder below.
433	   */
434	  char wskey_b64[32];
435	  {
436	    const char b64[] =
437	      "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
438	    int o = 0;
439	    int i;
440	    for (i = 0; i < 16; i += 3)
441	      {
442	        uint32_t v = (wskey[i] << 16);
443	        if (i + 1 < 16) v |= (wskey[i + 1] << 8);
444	        if (i + 2 < 16) v |= wskey[i + 2];
445	        wskey_b64[o++] = b64[(v >> 18) & 0x3f];
446	        wskey_b64[o++] = b64[(v >> 12) & 0x3f];
447	        wskey_b64[o++] = (i + 1 < 16) ? b64[(v >> 6) & 0x3f] : '=';
448	        wskey_b64[o++] = (i + 2 < 16) ? b64[v & 0x3f] : '=';
449	      }
450	
451	    wskey_b64[o] = '\0';
452	  }
453	
454	  snprintf(req, sizeof(req),
455	    "GET %s HTTP/1.1\r\n"
456	    "Host: %s\r\n"
457	    "Upgrade: websocket\r\n"
458	    "Connection: Upgrade\r\n"
459	    "Sec-WebSocket-Key: %s\r\n"
460	    "Sec-WebSocket-Version: 13\r\n"
461	    "Authorization: Bearer %s\r\n"
462	    "Device-Id: %s\r\n"
463	    "Client-Id: %s\r\n"
464	    "Protocol-Version: 1\r\n"
465	    "\r\n",
466	    path, host, wskey_b64, token, device_id, client_id);
467	
468	  printf("[xiaozhi] sending ws upgrade request (%zu bytes)\n", strlen(req));
469	
470	  ret = ws_tls_write_all(ws, (const uint8_t *)req, strlen(req));
471	  if (ret != 0)
472	    {
473	      return ret;
474	    }
475	
476	  /* Read the HTTP response line + headers until blank line. */
477	  {
478	    char line[256];
479	    int got101 = 0;
480	
481	    /* Read line-by-line until \r\n\r\n */
482	    for (;;)
483	      {
484	        size_t li = 0;
485	        char prev = 0;
486	
487	        while (li < sizeof(line) - 1)
488	          {
489	            uint8_t b;
490	            ret = ws_tls_read_all(ws, &b, 1);
491	            if (ret != 0)
492	              {
493	                return ret;
494	              }
495	
496	            line[li] = (char)b;
497	            if (line[li] == '\n' && prev == '\r')
498	              {
499	                break;
500	              }
501	
502	            prev = line[li];
503	            li++;
504	          }
505	
506	        line[li] = '\0';
507	
508	        /* Strip trailing \r\n */
509	        while (li > 0 && (line[li - 1] == '\r' || line[li - 1] == '\n'))
510	          {
511	            line[--li] = '\0';
512	          }
513	
514	        if (li == 0)
515	          {
516	            break;  /* blank line: end of headers */
517	          }
518	
519	        if (strstr(line, "101") != NULL && !got101)
520	          {
521	            got101 = 1;
522	          }
523	
524	        printf("[xiaozhi] <<< %s\n", line);
525	      }
526	
527	    if (!got101)
528	      {
529	        printf("[xiaozhi] ws upgrade failed (no 101)\n");
530	        return -EIO;
531	      }
532	  }
533	
534	  ws->connected = true;
535	  printf("[xiaozhi] WebSocket connected & upgraded\n");
536	  return 0;
537	}
538	
539	int xiaozhi_ws_send_text(struct xiaozhi_ws_s *ws, const char *data,
540	                         size_t len)
541	{
542	  if (!ws->connected)
543	    {
544	      return -ENOTCONN;
545	    }
546	
547	  return ws_send_frame(ws, WS_OPCODE_TEXT, (const uint8_t *)data, len);
548	}
549	
550	int xiaozhi_ws_send_binary(struct xiaozhi_ws_s *ws,
551	                           const uint8_t *data, size_t len)
552	{
553	  if (!ws->connected)
554	    {
555	      return -ENOTCONN;
556	    }
557	
558	  return ws_send_frame(ws, WS_OPCODE_BINARY, data, len);
559	}
560	
561	int xiaozhi_ws_recv(struct xiaozhi_ws_s *ws, const uint8_t **payload,
562	                    size_t *plen, bool *is_binary)
563	{
564	  uint8_t hdr[2];
565	  uint8_t mask[4];
566	  uint8_t opcode;
567	  bool masked;
568	  uint64_t plen64;
569	  int ret;
570	
571	  if (!ws->connected)
572	    {
573	      return -ENOTCONN;
574	    }
575	
576	  /* Read the first 2 bytes of the frame header. */
577	  ret = ws_tls_read_all(ws, hdr, 2);
578	  if (ret != 0)
579	    {
580	      return ret;
581	    }
582	
583	  opcode = hdr[0] & 0x0f;
584	  masked = (hdr[1] & WS_MASK_BIT) != 0;
585	  plen64 = hdr[1] & 0x7f;
586	
587	  if (plen64 == 126)
588	    {
589	      uint8_t ext[2];
590	      ret = ws_tls_read_all(ws, ext, 2);
591	      if (ret != 0)
592	        {
593	          return ret;
594	        }
595	
596	      plen64 = ((uint64_t)ext[0] << 8) | ext[1];
597	    }
598	  else if (plen64 == 127)
599	    {
600	      uint8_t ext[8];
601	      ret = ws_tls_read_all(ws, ext, 8);
602	      if (ret != 0)
603	        {
604	          return ret;
605	        }
606	
607	      plen64 = 0;
608	      for (int i = 0; i < 8; i++)
609	        {
610	          plen64 = (plen64 << 8) | ext[i];
611	        }
612	    }
613	
614	  if (masked)
615	    {
616	      ret = ws_tls_read_all(ws, mask, 4);
617	      if (ret != 0)
618	        {
619	          return ret;
620	        }
621	    }
622	
623	  if (plen64 > ws->rxbuf_cap)
624	    {
625	      printf("[xiaozhi] frame too large: %llu\n",
626	             (unsigned long long)plen64);
627	      return -EMSGSIZE;
628	    }
629	
630	  /* Read the payload. */
631	  if (plen64 > 0)
632	    {
633	      ret = ws_tls_read_all(ws, ws->rxbuf, plen64);
634	      if (ret != 0)
635	        {
636	          return ret;
637	        }
638	
639	      if (masked)
640	        {
641	          for (uint64_t i = 0; i < plen64; i++)
642	            {
643	              ws->rxbuf[i] ^= mask[i & 3];
644	            }
645	        }
646	    }
647	
648	  /* Handle control frames transparently. */
649	  if (opcode == WS_OPCODE_CLOSE)
650	    {
651	      printf("[xiaozhi] server sent close frame\n");
652	      ws->connected = false;
653	      return -ECONNRESET;
654	    }
655	
656	  if (opcode == WS_OPCODE_PING)
657	    {
658	      /* Echo as pong. */
659	      ws_send_frame(ws, WS_OPCODE_PONG, ws->rxbuf, plen64);
660	      return xiaozhi_ws_recv(ws, payload, plen, is_binary);
661	    }
662	
663	  if (opcode == WS_OPCODE_PONG)
664	    {
665	      /* Ignore. */
666	      return xiaozhi_ws_recv(ws, payload, plen, is_binary);
667	    }
668	
669	  /* Text or binary. */
670	  *payload    = ws->rxbuf;
671	  *plen       = plen64;
672	  *is_binary  = (opcode == WS_OPCODE_BINARY);
673	  return 0;
674	}
675	
676	void xiaozhi_ws_close(struct xiaozhi_ws_s *ws)
677	{
678	  if (ws->connected)
679	    {
680	      uint8_t close_frame[] = { 0x88, 0x00 };
681	      ws_tls_write_all(ws, close_frame, 2);
682	    }
683	
684	  mbedtls_ssl_close_notify(&ws->ssl);
685	  mbedtls_ssl_free(&ws->ssl);
686	  mbedtls_ssl_config_free(&ws->conf);
687	  mbedtls_ctr_drbg_free(&ws->ctr_drbg);
688	  mbedtls_entropy_free(&ws->entropy);
689	
690	  if (ws->fd >= 0)
691	    {
692	      close(ws->fd);
693	      ws->fd = -1;
694	    }
695	
696	  if (ws->rxbuf)
697	    {
698	      free(ws->rxbuf);
699	      ws->rxbuf = NULL;
700	    }
701	
702	  ws->connected = false;
703	}
