1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_audio.c
3	 *
4	 * Audio capture (mic -> Opus 16kHz) and playback (Opus 24kHz -> speaker)
5	 * using the Vela media framework in buffer mode. The framework performs
6	 * Opus encode/decode internally, so the application only reads/writes
7	 * encoded Opus frames.
8	 *
9	 * SPDX-License-Identifier: Apache-2.0
10	 ****************************************************************************/
11	
12	#include <nuttx/config.h>
13	
14	#include <stdio.h>
15	#include <string.h>
16	#include <errno.h>
17	
18	#include <media_recorder.h>
19	#include <media_player.h>
20	#include <media_defs.h>
21	
22	#include "xiaozhi_audio.h"
23	
24	/****************************************************************************
25	 * Pre-processor Definitions
26	 ****************************************************************************/
27	
28	/* Uplink: 16kHz mono Opus. */
29	#define XZ_RECORDER_OPTIONS \
30	  "format=opus:sample_rate=16000:ch_layout=mono:b=32000:vbr=0:level=1"
31	
32	/* Downlink: 24kHz mono Opus (xiaozhi server TTS sample rate). */
33	#define XZ_PLAYER_OPTIONS \
34	  "format=opus:sample_rate=24000:ch_layout=mono"
35	
36	/* Max single Opus frame we expect from the recorder / send to the player. */
37	#define XZ_OPUS_FRAME_MAX 400
38	
39	/****************************************************************************
40	 * Public Functions
41	 ****************************************************************************/
42	
43	int xiaozhi_audio_init(struct xiaozhi_audio_s *a)
44	{
45	  if (a == NULL)
46	    {
47	      return -EINVAL;
48	    }
49	
50	  memset(a, 0, sizeof(*a));
51	  return 0;
52	}
53	
54	int xiaozhi_audio_start_capture(struct xiaozhi_audio_s *a)
55	{
56	  int ret;
57	
58	  if (a == NULL)
59	    {
60	      return -EINVAL;
61	    }
62	
63	  /* Tear down any previous recorder. */
64	  if (a->recorder != NULL)
65	    {
66	      media_recorder_stop(a->recorder);
67	      media_recorder_close(a->recorder);
68	      a->recorder = NULL;
69	    }
70	
71	  a->recorder = media_recorder_open(MEDIA_SOURCE_MIC);
72	  if (a->recorder == NULL)
73	    {
74	      printf("[xiaozhi] media_recorder_open failed\n");
75	      return -EIO;
76	    }
77	
78	  /* Buffer mode: url = NULL. The framework encodes to Opus; we read the
79	   * encoded frames back via media_recorder_read_data().
80	   */
81	  ret = media_recorder_prepare(a->recorder, NULL, XZ_RECORDER_OPTIONS);
82	  if (ret < 0)
83	    {
84	      printf("[xiaozhi] recorder prepare failed: %d\n", ret);
85	      media_recorder_close(a->recorder);
86	      a->recorder = NULL;
87	      return ret;
88	    }
89	
90	  ret = media_recorder_start(a->recorder);
91	  if (ret < 0)
92	    {
93	      printf("[xiaozhi] recorder start failed: %d\n", ret);
94	      media_recorder_close(a->recorder);
95	      a->recorder = NULL;
96	      return ret;
97	    }
98	
99	  printf("[xiaozhi] capture started (16k opus)\n");
100	  return 0;
101	}
102	
103	ssize_t xiaozhi_audio_read_opus(struct xiaozhi_audio_s *a,
104	                                uint8_t *buf, size_t maxlen)
105	{
106	  if (a == NULL || a->recorder == NULL || buf == NULL)
107	    {
108	      return -EINVAL;
109	    }
110	
111	  /* Blocks until an encoded Opus frame is available. */
112	  return media_recorder_read_data(a->recorder, buf, maxlen);
113	}
114	
115	int xiaozhi_audio_stop_capture(struct xiaozhi_audio_s *a)
116	{
117	  if (a == NULL || a->recorder == NULL)
118	    {
119	      return -EINVAL;
120	    }
121	
122	  media_recorder_stop(a->recorder);
123	  media_recorder_close(a->recorder);
124	  a->recorder = NULL;
125	  printf("[xiaozhi] capture stopped\n");
126	  return 0;
127	}
128	
129	int xiaozhi_audio_start_playback(struct xiaozhi_audio_s *a)
130	{
131	  int ret;
132	
133	  if (a == NULL)
134	    {
135	      return -EINVAL;
136	    }
137	
138	  if (a->player != NULL)
139	    {
140	      media_player_stop(a->player);
141	      media_player_close(a->player, 0);
142	      a->player = NULL;
143	    }
144	
145	  a->player = media_player_open(MEDIA_STREAM_MUSIC);
146	  if (a->player == NULL)
147	    {
148	      printf("[xiaozhi] media_player_open failed\n");
149	      return -EIO;
150	    }
151	
152	  /* Buffer mode: url = NULL. The framework decodes Opus; we feed encoded
153	   * frames via media_player_write_data().
154	   */
155	  ret = media_player_prepare(a->player, NULL, XZ_PLAYER_OPTIONS);
156	  if (ret < 0)
157	    {
158	      printf("[xiaozhi] player prepare failed: %d\n", ret);
159	      media_player_close(a->player, 0);
160	      a->player = NULL;
161	      return ret;
162	    }
163	
164	  ret = media_player_start(a->player);
165	  if (ret < 0)
166	    {
167	      printf("[xiaozhi] player start failed: %d\n", ret);
168	      media_player_close(a->player, 0);
169	      a->player = NULL;
170	      return ret;
171	    }
172	
173	  printf("[xiaozhi] playback started (24k opus)\n");
174	  return 0;
175	}
176	
177	int xiaozhi_audio_write_opus(struct xiaozhi_audio_s *a,
178	                             const uint8_t *data, size_t len)
179	{
180	  ssize_t ret;
181	
182	  if (a == NULL || a->player == NULL || data == NULL)
183	    {
184	      return -EINVAL;
185	    }
186	
187	  ret = media_player_write_data(a->player, data, len);
188	  if (ret < 0)
189	    {
190	      printf("[xiaozhi] player write_data failed: %zd\n", ret);
191	      return ret;
192	    }
193	
194	  return 0;
195	}
196	
197	int xiaozhi_audio_stop_playback(struct xiaozhi_audio_s *a)
198	{
199	  if (a == NULL || a->player == NULL)
200	    {
201	      return -EINVAL;
202	    }
203	
204	  media_player_stop(a->player);
205	  media_player_close(a->player, 0);
206	  a->player = NULL;
207	  printf("[xiaozhi] playback stopped\n");
208	  return 0;
209	}
210	
211	void xiaozhi_audio_deinit(struct xiaozhi_audio_s *a)
212	{
213	  if (a == NULL)
214	    {
215	      return;
216	    }
217	
218	  if (a->recorder != NULL)
219	    {
220	      media_recorder_stop(a->recorder);
221	      media_recorder_close(a->recorder);
222	      a->recorder = NULL;
223	    }
224	
225	  if (a->player != NULL)
226	    {
227	      media_player_stop(a->player);
228	      media_player_close(a->player, 0);
229	      a->player = NULL;
230	    }
231	}
