1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_ota.c
3	 *
4	 * Xiaozhi OTA: POST https://api.tenclass.net/xiaozhi/ota/ with Device-Id,
5	 * parse the JSON response to extract websocket.url and websocket.token.
6	 *
7	 * SPDX-License-Identifier: Apache-2.0
8	 ****************************************************************************/
9	
10	/****************************************************************************
11	 * Included Files
12	 ****************************************************************************/
13	#include <nuttx/config.h>
14	
15	#include <stdio.h>
16	#include <string.h>
17	#include <stdlib.h>
18	
