24	/****************************************************************************
25	 * Pre-processor Definitions
26	 ****************************************************************************/
27	
28	#define OTA_URL "https://api.tenclass.net/xiaozhi/ota/"
29	#define OTA_BUF_SIZE  4096
30	
31	/****************************************************************************
32	 * Private Types
33	 ****************************************************************************/
34	
35	/* Context passed to the sink callback to accumulate the response body. */
36	
37	struct ota_sink_ctx_s
38	{
39	  char *buf;
40	  size_t cap;
41	  size_t len;
42	};
43	
44	/****************************************************************************
45	 * Private Functions
46	 ****************************************************************************/
47	
48	/* sink_callback: consume response body (the OTA JSON) into our buffer. */
49	
50	static CODE int ota_sink_callback(FAR char **buffer, int offset, int datend,
51	                                  FAR int *buflen, FAR void *arg)
52	{
53	  struct ota_sink_ctx_s *ctx = arg;
54	  int chunk = datend - offset;
55	
56	  if (chunk <= 0)
57	    {
58	      return 0;
59	    }
60	
61	  if (ctx->len + chunk >= ctx->cap)
62	    {
63	      chunk = ctx->cap - ctx->len - 1;
64	      if (chunk <= 0)
65	        {
66	          return -ENOMEM;
67	        }
68	    }
69	
70	  memcpy(ctx->buf + ctx->len, *buffer + offset, chunk);
71	  ctx->len += chunk;
72	  ctx->buf[ctx->len] = '\0';
73	  return 0;
74	}
75	
76	/****************************************************************************
77	 * Public Functions
78	 ****************************************************************************/
79	
80	/* Build the fixed OTA request body. mac is the device MAC string. */
81	
82	static int build_ota_body(const char *mac, FAR char *out, size_t outsz)
83	{
84	  /* A minimal but server-accepted OTA body. The xiaozhi server is tolerant
85	   * about most fields; mac_address is the important one (also sent as the
86	   * Device-Id header).
87	   */
88	
89	  return snprintf(out, outsz,
90	    "{\"flash_size\":16777216,\"minimum_free_heap_size\":8318916,"
91	    "\"mac_address\":\"%s\",\"chip_model_name\":\"esp32s3\","
92	    "\"chip_info\":{\"model\":9,\"cores\":2,\"revision\":2,\"features\":18},"
93	    "\"application\":{\"name\":\"xiaozhi\",\"version\":\"0.9.9\","
94	    "\"compile_time\":\"Jan 22 2025T20:40:23Z\","
95	    "\"idf_version\":\"v5.3.2-dirty\","
96	    "\"elf_sha256\":\"22986216df095587c42f8aeb06b239781c68ad8df80321e260556da7fcf5f522\"},"
97	    "\"partition_table\":[],\"ota\":{\"label\":\"factory\"},"
98	    "\"board\":{\"type\":\"bread-compact-wifi\",\"ssid\":\"mzy\","
99	    "\"rssi\":-58,\"channel\":6,\"ip\":\"192.168.124.38\","
100	    "\"mac\":\"cc:ba:97:20:b4:bc\"}}",
101	    mac);
102	}
103	
104	/* Perform the OTA POST and fill ota_out with ws_url / ws_token.
105	 * Returns 0 on success, negative errno on failure.
106	 */
107	
108	int xiaozhi_ota_fetch(const char *mac, FAR struct xiaozhi_ota_config_s *ota_out)
109	{
110	  struct webclient_context ctx;
111	  char body[OTA_BUF_SIZE];
112	  struct ota_sink_ctx_s sink;
113	  char buf[OTA_BUF_SIZE];
114	  const char *headers[2];
115	  int ret;
116	  size_t bodylen;
117	  cJSON *root = NULL;
118	  cJSON *ws = NULL;
119	  cJSON *url = NULL;
120	  cJSON *token = NULL;
121	
122	  if (mac == NULL || ota_out == NULL)
123	    {
124	      return -EINVAL;
125	    }
126	
127	  memset(ota_out, 0, sizeof(*ota_out));
128	
129	  /* Build request body. */
130	  bodylen = build_ota_body(mac, body, sizeof(body));
131	
132	  /* Device-Id header = MAC. */
133	  headers[0] = "Device-Id: ";
134	  /* The webclient appends header lines as-is; we pass a small array. */
135	  /* NOTE: webclient treats each "headers[]" entry as a full header line
136	   * including the trailing CRLF-less content; it appends "\r\n".
137	   * We build the Device-Id header dynamically below.
138	   */
139	
140	  /* The headers array requires fully formed header strings. We can't
141	   * use a string literal with the MAC embedded, so build it in `buf`
142	   * side buffer. Reuse a small static-ish local.
143	   */
144	  {
145	    static char device_id_header[64];
146	    snprintf(device_id_header, sizeof(device_id_header),
147	             "Device-Id: %s", mac);
148	    headers[0] = device_id_header;
149	    headers[1] = "Content-Type: application/json";
150	  }
151	
152	  /* Set up sink to accumulate the response body. */
153	  memset(buf, 0, sizeof(buf));
154	  sink.buf = buf;
155	  sink.cap = sizeof(buf);
156	  sink.len = 0;
157	
158	  webclient_set_defaults(&ctx);
159	  ctx.method              = "POST";
160	  ctx.url                 = OTA_URL;
161	  ctx.protocol_version    = WEBCLIENT_PROTOCOL_VERSION_HTTP_1_1;
162	  ctx.buffer              = buf;            /* shared scratch buffer */
163	  ctx.buflen              = sizeof(buf);
164	  ctx.headers             = headers;
165	  ctx.nheaders            = 2;
166	  ctx.bodylen             = bodylen;
167	  ctx.timeout_sec         = 15;
168	  ctx.sink_callback       = ota_sink_callback;
169	  ctx.sink_callback_arg   = &sink;
170	
171	  /* Provide the request body via the static-body helper. */
172	  webclient_set_static_body(&ctx, body, bodylen);
173	
174	  ret = webclient_perform(&ctx);
175	  if (ret != 0)
176	    {
177	      printf("[xiaozhi] OTA webclient_perform failed: %d\n", ret);
178	      return ret;
179	    }
180	
181	  printf("[xiaozhi] OTA HTTP status=%u, body=%zu bytes\n",
182	         ctx.http_status, sink.len);
183	
184	  if (ctx.http_status != 200 || sink.len == 0)
185	    {
186	      printf("[xiaozhi] OTA unexpected status/body: %u\n", ctx.http_status);
187	      return -EIO;
188	    }
189	
190	  /* Parse JSON: { "websocket": { "url": "...", "token": "..." } } */
191	  root = cJSON_ParseWithLength(sink.buf, sink.len);
192	  if (root == NULL)
193	    {
194	      printf("[xiaozhi] OTA JSON parse failed\n");
195	      return -EIO;
196	    }
197	
198	  ws    = cJSON_GetObjectItem(root, "websocket");
199	  url   = cJSON_GetObjectItem(ws, "url");
200	  token = cJSON_GetObjectItem(ws, "token");
201	
202	  if (!cJSON_IsString(url) || !cJSON_IsString(token))
203	    {
204	      printf("[xiaozhi] OTA: websocket.url/token missing\n");
205	      cJSON_Delete(root);
206	      return -EIO;
207	    }
208	
209	  strncpy(ota_out->ws_url, url->valuestring, sizeof(ota_out->ws_url) - 1);
210	  strncpy(ota_out->ws_token, token->valuestring,
211	          sizeof(ota_out->ws_token) - 1);
212	
213	  printf("[xiaozhi] OTA OK: ws_url=%s token=%s\n",
214	         ota_out->ws_url, ota_out->ws_token);
215	
216	  cJSON_Delete(root);
217	  return 0;
218	}
