/****************************************************************************
 * apps/examples/xiaozhi_voice/include/mcp_server.h
 *
 * MCP (Model Context Protocol) tool server for Xiaozhi voice assistant.
 * Allows the AI to call device-side tools (stopwatch, clock, alarm, etc.)
 * via the xiaozhi websocket protocol.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#ifndef MCP_SERVER_H
#define MCP_SERVER_H

#include <stdint.h>
#include <stdbool.h>
#include <cJSON.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define MCP_MAX_TOOLS 16
#define MCP_TOOL_NAME_MAX 64
#define MCP_TOOL_DESC_MAX 128

/****************************************************************************
 * Public Types
 ****************************************************************************/

/* Tool argument types - simplified for embedded use. */

enum mcp_arg_type_e
{
  MCP_ARG_NONE = 0,    /* No argument */
  MCP_ARG_STRING,      /* String argument */
  MCP_ARG_INT,         /* Integer argument */
  MCP_ARG_BOOL,        /* Boolean argument */
};

/* Tool argument value. */

union mcp_arg_value_u
{
  const char *s;
  int i;
  bool b;
};

/* Tool callback: called when the AI invokes a tool.
 * args is a cJSON object (may be NULL if no arguments).
 * Must return a cJSON object (caller frees it) or NULL on error.
 */

typedef cJSON *(*mcp_tool_cb_t)(const cJSON *args);

/* Tool registration entry. */

struct mcp_tool_s
{
  char name[MCP_TOOL_NAME_MAX];
  char description[MCP_TOOL_DESC_MAX];
  mcp_tool_cb_t callback;
};

/* MCP server context. */

struct mcp_server_s
{
  struct mcp_tool_s tools[MCP_MAX_TOOLS];
  int tool_count;
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* Initialize the MCP server. Must be called once before any other
 * mcp_server_* functions.
 */

void mcp_server_init(void);

/* Register a tool with the MCP server. Returns 0 on success, -1 if
 * the tool table is full or name is NULL.
 */

int mcp_server_add_tool(const char *name,
                        const char *description,
                        mcp_tool_cb_t callback);

/* Handle an incoming MCP message from the server. The message is a
 * cJSON object with type="mcp". This function processes tool_calls
 * and sends responses back via the provided send_json callback.
 *
 * msg: the full JSON message (owned by caller, not freed here)
 * send_json_cb: callback to send a JSON message back to the server
 *               int send_json_cb(cJSON *msg) - returns 0 on success
 *
 * Returns 0 on success, -1 on error.
 */

int mcp_server_handle_message(const cJSON *msg,
                              int (*send_json_cb)(cJSON *));

/* Build the "features" object for the hello handshake. Adds
 * {"mcp": true} to the given hello JSON object.
 */

void mcp_server_add_hello_features(cJSON *hello);

#endif /* MCP_SERVER_H */

/****************************************************************************
 * apps/examples/xiaozhi_voice/mcp_server.c
 *
 * MCP (Model Context Protocol) tool server implementation.
 * Manages tool registration and dispatch for xiaozhi voice assistant.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#include <netutils/cJSON.h>

#include "mcp_server.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct mcp_server_s g_mcp;

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void mcp_server_init(void)
{
  memset(&g_mcp, 0, sizeof(g_mcp));
  printf("[mcp] server initialized, max %d tools\n", MCP_MAX_TOOLS);
}

int mcp_server_add_tool(const char *name,
                        const char *description,
                        mcp_tool_cb_t callback)
{
  if (name == NULL || callback == NULL)
    {
      return -1;
    }

  if (g_mcp.tool_count >= MCP_MAX_TOOLS)
    {
      printf("[mcp] ERROR: tool table full, cannot add '%s'\n", name);
      return -1;
    }

  struct mcp_tool_s *tool = &g_mcp.tools[g_mcp.tool_count];
  strncpy(tool->name, name, MCP_TOOL_NAME_MAX - 1);
  tool->name[MCP_TOOL_NAME_MAX - 1] = '\0';
  strncpy(tool->description, description, MCP_TOOL_DESC_MAX - 1);
  tool->description[MCP_TOOL_DESC_MAX - 1] = '\0';
  tool->callback = callback;

  g_mcp.tool_count++;
  printf("[mcp] registered tool: %s — %s\n", name, description);
  return 0;
}

static struct mcp_tool_s *find_tool(const char *name)
{
  int i;
  for (i = 0; i < g_mcp.tool_count; i++)
    {
      if (strcmp(g_mcp.tools[i].name, name) == 0)
        {
          return &g_mcp.tools[i];
        }
    }

  return NULL;
}

int mcp_server_handle_message(const cJSON *msg,
                              int (*send_json_cb)(cJSON *))
{
  if (msg == NULL || send_json_cb == NULL)
    {
      return -1;
    }

  /* The server sends: {"type":"mcp","tool_calls":[{"id":"...","name":"...","arguments":{}}]} */

  cJSON *tool_calls = cJSON_GetObjectItem(msg, "tool_calls");
  if (!cJSON_IsArray(tool_calls))
    {
      printf("[mcp] received mcp message without tool_calls array\n");
      return -1;
    }

  int n_calls = cJSON_GetArraySize(tool_calls);
  int i;

  for (i = 0; i < n_calls; i++)
    {
      cJSON *call = cJSON_GetArrayItem(tool_calls, i);
      if (!cJSON_IsObject(call))
        {
          continue;
        }

      cJSON *id_item = cJSON_GetObjectItem(call, "id");
      cJSON *name_item = cJSON_GetObjectItem(call, "name");
      cJSON *args_item = cJSON_GetObjectItem(call, "arguments");

      const char *call_id = cJSON_IsString(id_item) ? id_item->valuestring : "";
      const char *tool_name = cJSON_IsString(name_item) ? name_item->valuestring : "";

      printf("[mcp] tool_call: id=%s name=%s\n", call_id, tool_name);

      struct mcp_tool_s *tool = find_tool(tool_name);
      cJSON *result = NULL;

      if (tool != NULL)
        {
          printf("[mcp] executing tool: %s\n", tool_name);
          result = tool->callback(args_item);
        }
      else
        {
          printf("[mcp] unknown tool: %s\n", tool_name);
          result = cJSON_CreateString("error: unknown tool");
        }

      /* Build the tool_result response. */

      cJSON *resp = cJSON_CreateObject();
      cJSON_AddStringToObject(resp, "type", "mcp");

      cJSON *results = cJSON_CreateArray();
      cJSON *entry = cJSON_CreateObject();
      cJSON_AddStringToObject(entry, "id", call_id);

      if (result != NULL)
        {
          cJSON_AddItemToObject(entry, "result", result);
        }
      else
        {
          cJSON_AddStringToObject(entry, "result", "null");
        }

      cJSON_AddItemToArray(results, entry);
      cJSON_AddItemToObject(resp, "tool_results", results);

      /* Send response back to server. */

      int ret = send_json_cb(resp);
      cJSON_Delete(resp);

      if (ret != 0)
        {
          printf("[mcp] failed to send tool_result for %s\n", tool_name);
        }
    }

  return 0;
}

void mcp_server_add_hello_features(cJSON *hello)
{
  if (hello == NULL)
    {
      return;
    }

  cJSON *features = cJSON_GetObjectItem(hello, "features");
  if (features == NULL)
    {
      features = cJSON_CreateObject();
      cJSON_AddItemToObject(hello, "features", features);
    }

  cJSON_AddBoolToObject(features, "mcp", true);
  printf("[mcp] added mcp=true to hello features\n");
}

