180	static void gesture_event_handler(lv_event_t *e)
181	{
182	    lv_event_code_t code = lv_event_get_code(e);
183	    if (code != LV_EVENT_PRESSED && code != LV_EVENT_RELEASED) return;
184	    lv_obj_t *obj = lv_event_get_target(e);
185	    lv_indev_t *indev = lv_event_get_indev(e);
186	    
187	    if (!indev) return;
188	    
189	    lv_point_t point;
190	    lv_indev_get_point(indev, &point);
191	    
192	    switch (code) {
193	        case LV_EVENT_PRESSED:
194	            gesture_start_x = point.x;
195	            gesture_start_y = point.y;
196	            gesture_in_progress = true;
197	            break;
198	        case LV_EVENT_RELEASED:
199	            if (gesture_in_progress) {

200	            if (gesture_in_progress) {
201	                int delta_x = point.x - gesture_start_x;
202	                int delta_y = point.y - gesture_start_y;
203	                
204	                // 检查是否是右滑手势（水平滑动距离大于阈值，且垂直滑动较小）
205	                if (delta_x > gesture_threshold && abs(delta_y) < gesture_threshold) {
206	                    // 修改：右滑隐藏秒表界面
207	                    exit_stopwatch();
208	                }
209	                
210	                gesture_in_progress = false;
211	            }
212	            break;
213	        default:
214	            break;
215	    }
216	}
