int mcp_server_handle_message(const cJSON *msg,
                              int (*send_json_cb)(cJSON *))
{
  if (msg == NULL || send_json_cb == NULL)
    {
      return -1;
    }

  /* Server sends: {"type":"mcp","payload":{...},"session_id":"..."} */

  cJSON *payload = cJSON_GetObjectItem(msg, "payload");
  if (!cJSON_IsObject(payload))
    {
      printf("[mcp] mcp message has no payload\n");
      return -1;
    }

  /* Handle JSON-RPC method dispatch inside payload. */

  cJSON *method = cJSON_GetObjectItem(payload, "method");
  cJSON *id_item = cJSON_GetObjectItem(payload, "id");

  if (cJSON_IsString(method))
    {
      const char *method_name = method->valuestring;
      printf("[mcp] method: %s\n", method_name);

      if (strcmp(method_name, "initialize") == 0)
        {
          /* Respond with server capabilities (JSON-RPC result). */

          cJSON *resp = cJSON_CreateObject();
          cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
          if (id_item != NULL)
            {
              cJSON_AddItemReferenceToObject(resp, "id", id_item);
            }

          cJSON *result = cJSON_CreateObject();
          cJSON_AddStringToObject(result, "protocolVersion", "2024-11-05");

          cJSON *caps = cJSON_CreateObject();
          cJSON *tools_caps = cJSON_CreateObject();
          cJSON_AddBoolToObject(tools_caps, "listChanged", false);
          cJSON_AddItemToObject(caps, "tools", tools_caps);
          cJSON_AddItemToObject(result, "capabilities", caps);

          cJSON *server_info = cJSON_CreateObject();
          cJSON_AddStringToObject(server_info, "name", "xiaozhi-device");
          cJSON_AddStringToObject(server_info, "version", "1.0.0");
          cJSON_AddItemToObject(result, "serverInfo", server_info);

          cJSON_AddItemToObject(resp, "result", result);

          printf("[mcp] sending initialize response\n");
          int ret = send_json_cb(resp);
          cJSON_Delete(resp);
          return ret;
        }
      else if (strcmp(method_name, "notifications/tools/list_changed") == 0)
        {
          printf("[mcp] tools list changed notification, ignored\n");
          return 0;
        }
    }

  /* Handle tool_calls — may be at top level or inside payload. */

  cJSON *tool_calls = cJSON_GetObjectItem(msg, "tool_calls");
  if (!cJSON_IsArray(tool_calls))
    {
      tool_calls = cJSON_GetObjectItem(payload, "tool_calls");
    }

  if (!cJSON_IsArray(tool_calls))
    {
      printf("[mcp] no tool_calls in message\n");
      return -1;
    }

  int n_calls = cJSON_GetArraySize(tool_calls);
  int i;

  for (i = 0; i < n_calls; i++)
    {
      cJSON *call = cJSON_GetArrayItem(tool_calls, i);
      if (!cJSON_IsObject(call))
        {
          continue;
        }

      cJSON *call_id_item = cJSON_GetObjectItem(call, "id");
      cJSON *name_item = cJSON_GetObjectItem(call, "name");
      cJSON *args_item = cJSON_GetObjectItem(call, "arguments");

      const char *call_id = cJSON_IsString(call_id_item) ?
                            call_id_item->valuestring : "";
      const char *tool_name = cJSON_IsString(name_item) ?
                              name_item->valuestring : "";

      printf("[mcp] tool_call: id=%s name=%s\n", call_id, tool_name);

      struct mcp_tool_s *tool = find_tool(tool_name);
      cJSON *result = NULL;

      if (tool != NULL)
        {
          printf("[mcp] executing tool: %s\n", tool_name);
          result = tool->callback(args_item);
        }
      else
        {
          printf("[mcp] unknown tool: %s\n", tool_name);
          result = cJSON_CreateString("error: unknown tool");
        }

      /* Build tool_results response. */

      cJSON *resp = cJSON_CreateObject();
      cJSON_AddStringToObject(resp, "type", "mcp");

      cJSON *results = cJSON_CreateArray();
      cJSON *entry = cJSON_CreateObject();
      cJSON_AddStringToObject(entry, "id", call_id);

      if (result != NULL)
        {
          cJSON_AddItemToObject(entry, "result", result);
        }
      else
        {
          cJSON_AddStringToObject(entry, "result", "null");
        }

      cJSON_AddItemToArray(results, entry);
      cJSON_AddItemToObject(resp, "tool_results", results);

      int ret = send_json_cb(resp);
      cJSON_Delete(resp);

      if (ret != 0)
        {
          printf("[mcp] failed to send tool_result for %s\n", tool_name);
        }
    }

  return 0;
}

