1	/****************************************************************************
2	 * apps/examples/xiaozhi_voice/xiaozhi_ota_tls.c
3	 *
4	 * mbedtls-backed webclient_tls_ops: lets the webclient (used by the OTA
5	 * POST) speak https://. Without this, webclient sees tls_ops==NULL for an
6	 * "https" URL and rejects it with -ENOTSUP.
7	 *
8	 * connect():  resolve host, TCP-connect, run the mbedtls handshake.
9	 *              Returns an opaque webclient_tls_connection* (our struct).
10	 * send/recv:   wrap mbedtls_ssl_write / mbedtls_ssl_read, mapping the
11	 *              MBEDTLS_ERR_SSL_WANT_* retry codes to -EAGAIN for webclient.
12	 * get_poll_info: hand back the underlying TCP fd for poll-based waits.
13	 * close():     tear down TLS + socket.
14	 *
15	 * Server certificate verification is skipped (MBEDTLS_VERIFY_NONE) to keep
16	 * the embedded build simple; the OTA response carries only a token, and the
17	 * subsequent wss connection (xiaozhi_ws.c) is the real authenticated channel.
18	 *
19	 * SPDX-License-Identifier: Apache-2.0
20	 ****************************************************************************/
21	
22	#include <nuttx/config.h>
23	
24	#include <stdio.h>
25	#include <string.h>
26	#include <stdlib.h>
27	#include <errno.h>
28	#include <unistd.h>
