35	#include <mbedtls/entropy.h>
36	#include <mbedtls/ctr_drbg.h>
37	#include <mbedtls/net_sockets.h>
38	
39	#include <netutils/webclient.h>
40	
41	/****************************************************************************
42	 * Private Types
43	 ****************************************************************************/
44	
45	/* The webclient_tls_connection the TLS ops hand back to webclient. */
46	struct xz_tls_conn_s
47	{
48	  int                      fd;       /* underlying TCP socket */
49	  mbedtls_ssl_context      ssl;
50	  mbedtls_ssl_config       conf;
51	  mbedtls_entropy_context  entropy;
52	  mbedtls_ctr_drbg_context ctr_drbg;
53	};
54	
55	/****************************************************************************
56	 * Private Functions
57	 ****************************************************************************/
58	
59	/* BIO send/recv for mbedtls over the plain TCP fd. */
60	static int xz_bio_send(void *ctx, const unsigned char *buf, size_t len)
61	{
62	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)ctx;
63	  ssize_t ret = send(c->fd, buf, len, 0);
64	  if (ret < 0)
65	    {
66	      return MBEDTLS_ERR_NET_SEND_FAILED;
67	    }
68	
69	  return (int)ret;
70	}
71	
72	static int xz_bio_recv(void *ctx, unsigned char *buf, size_t len)
73	{
74	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)ctx;
75	  ssize_t ret = recv(c->fd, buf, len, 0);
76	  if (ret < 0)
77	    {
78	      return MBEDTLS_ERR_NET_RECV_FAILED;
79	    }
80	
81	  if (ret == 0)
82	    {
83	      return MBEDTLS_ERR_SSL_WANT_READ;
84	    }
85	
86	  return (int)ret;
87	}
