89	/* connect: DNS -> socket -> TCP connect -> TLS handshake.
90	 * Matches the webclient_tls_ops::connect signature.
91	 */
92	static int xz_tls_connect(FAR void *ctx, FAR const char *hostname,
93	                          FAR const char *port, unsigned int timeout_second,
94	                          FAR struct webclient_tls_connection **connp)
95	{
96	  struct xz_tls_conn_s *c;
97	  struct hostent *he;
98	  struct sockaddr_in server;
99	  int portnum = atoi(port);
100	  int ret;
101	
102	  (void)ctx;
103	  (void)timeout_second;
104	
105	  printf("[xiaozhi] ota-tls: connect %s:%s\n", hostname, port);
106	
107	  c = calloc(1, sizeof(*c));
108	  if (c == NULL)
109	    {
110	      return -ENOMEM;
111	    }
112	
113	  c->fd = -1;
114	
115	  /* --- DNS --- */
116	  he = gethostbyname(hostname);
117	  if (he == NULL)
118	    {
119	      printf("[xiaozhi] ota-tls: DNS failed for %s\n", hostname);
120	      ret = -EHOSTUNREACH;
121	      goto err_free;
122	    }
123	
124	  /* --- TCP socket + connect --- */
125	  c->fd = socket(AF_INET, SOCK_STREAM, 0);
126	  if (c->fd < 0)
127	    {
128	      printf("[xiaozhi] ota-tls: socket failed: %d\n", errno);
129	      ret = -EIO;
130	      goto err_free;
131	    }
132	
133	  memset(&server, 0, sizeof(server));
134	  server.sin_family = AF_INET;
135	  server.sin_port   = htons(portnum);
136	  memcpy(&server.sin_addr, he->h_addr_list[0], he->h_length);
137	
138	  printf("[xiaozhi] ota-tls: TCP connect %s:%d\n",
139	         inet_ntoa(server.sin_addr), portnum);
140	
141	  if (connect(c->fd, (struct sockaddr *)&server, sizeof(server)) < 0)
142	    {
143	      printf("[xiaozhi] ota-tls: TCP connect failed: %d\n", errno);
144	      ret = -ECONNREFUSED;
145	      goto err_sock;
146	    }
147	
148	  /* --- mbedtls setup --- */
149	  mbedtls_ssl_init(&c->ssl);
150	  mbedtls_ssl_config_init(&c->conf);
151	  mbedtls_entropy_init(&c->entropy);
152	  mbedtls_ctr_drbg_init(&c->ctr_drbg);
153	
154	  ret = mbedtls_ctr_drbg_seed(&c->ctr_drbg, mbedtls_entropy_func,
155	                              &c->entropy,
156	                              (const unsigned char *)"xiaozhi", 7);
157	  if (ret != 0)
158	    {
159	      printf("[xiaozhi] ota-tls: drbg seed failed: -0x%x\n", -ret);
160	      ret = -EIO;
161	      goto err_tls;
162	    }
163	
164	  ret = mbedtls_ssl_config_defaults(&c->conf, MBEDTLS_SSL_IS_CLIENT,
165	                                    MBEDTLS_SSL_TRANSPORT_STREAM,
166	                                    MBEDTLS_SSL_PRESET_DEFAULT);
167	  if (ret != 0)
168	    {
169	      printf("[xiaozhi] ota-tls: ssl config failed: -0x%x\n", -ret);
170	      ret = -EIO;
171	      goto err_tls;
172	    }
173	
174	  mbedtls_ssl_conf_authmode(&c->conf, MBEDTLS_SSL_VERIFY_NONE);
175	  mbedtls_ssl_conf_rng(&c->conf, mbedtls_ctr_drbg_random, &c->ctr_drbg);
176	
177	  ret = mbedtls_ssl_setup(&c->ssl, &c->conf);
178	  if (ret != 0)
179	    {
180	      printf("[xiaozhi] ota-tls: ssl setup failed: -0x%x\n", -ret);
181	      ret = -EIO;
182	      goto err_tls;
183	    }
184	
185	  /* SNI so the server serves the right cert. */
186	  mbedtls_ssl_set_hostname(&c->ssl, hostname);
187	  mbedtls_ssl_set_bio(&c->ssl, c, xz_bio_send, xz_bio_recv, NULL);
188	
189	  /* --- TLS handshake --- */
190	  printf("[xiaozhi] ota-tls: TLS handshake\n");
191	  while ((ret = mbedtls_ssl_handshake(&c->ssl)) != 0)
192	    {
193	      if (ret != MBEDTLS_ERR_SSL_WANT_READ &&
194	          ret != MBEDTLS_ERR_SSL_WANT_WRITE)
195	        {
196	          printf("[xiaozhi] ota-tls: handshake failed: -0x%x\n", -ret);
197	          ret = -EIO;
198	          goto err_tls;
199	        }
200	    }
201	
202	  printf("[xiaozhi] ota-tls: TLS handshake complete\n");
203	
204	  *connp = (struct webclient_tls_connection *)c;
205	  return 0;
206	
207	err_tls:
208	  mbedtls_ssl_free(&c->ssl);
209	  mbedtls_ssl_config_free(&c->conf);
210	  mbedtls_ctr_drbg_free(&c->ctr_drbg);
211	  mbedtls_entropy_free(&c->entropy);
212	
213	err_sock:
214	  if (c->fd >= 0)
215	    {
216	      close(c->fd);
217	    }
218	
219	err_free:
220	  free(c);
221	  return ret;
222	}
223	
224	static ssize_t xz_tls_send(FAR void *ctx,
225	                           FAR struct webclient_tls_connection *conn,
226	                           FAR const void *buf, size_t len)
227	{
228	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)conn;
229	  int ret;
230	  (void)ctx;
231	
232	  ret = mbedtls_ssl_write(&c->ssl, (const unsigned char *)buf, len);
233	  if (ret == MBEDTLS_ERR_SSL_WANT_READ ||
234	      ret == MBEDTLS_ERR_SSL_WANT_WRITE)
235	    {
236	      return -EAGAIN;
237	    }
238	
239	  if (ret < 0)
240	    {
241	      printf("[xiaozhi] ota-tls: send err -0x%x (len=%zu)\n", -ret, len);
242	      return -EIO;
243	    }
244	
245	  return ret;
246	}
247	
248	static ssize_t xz_tls_recv(FAR void *ctx,
249	                            FAR struct webclient_tls_connection *conn,
250	                            FAR void *buf, size_t len)
251	{
252	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)conn;
253	  int ret;
254	  (void)ctx;
255	
256	  ret = mbedtls_ssl_read(&c->ssl, (unsigned char *)buf, len);
257	  if (ret == MBEDTLS_ERR_SSL_WANT_READ ||
258	      ret == MBEDTLS_ERR_SSL_WANT_WRITE)
259	    {
260	      /* No data yet on a blocking socket — shouldn't normally happen
261	       * mid-response, but if it does, surface it so webclient can poll.
262	       */
263	      return -EAGAIN;
264	    }
265	
266	  if (ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY || ret == 0)
267	    {
268	      /* Server sent a clean TLS close. Distinguish "no response at all"
269	       * (server hung up before sending anything) from a post-data close.
270	       */
271	      printf("[xiaozhi] ota-tls: peer closed (close_notify)\n");
272	      return 0;   /* let webclient treat as clean EOF, not a hard reset */
273	    }
274	
275	  if (ret < 0)
276	    {
277	      printf("[xiaozhi] ota-tls: recv err -0x%x\n", -ret);
278	      return -EIO;
279	    }
280	
281	  return ret;
282	}
283	
284	static int xz_tls_close(FAR void *ctx,
285	                         FAR struct webclient_tls_connection *conn)
286	{
287	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)conn;
288	  (void)ctx;
289	
290	  if (c == NULL)
291	    {
292	      return 0;
293	    }
294	
295	  mbedtls_ssl_close_notify(&c->ssl);
296	  mbedtls_ssl_free(&c->ssl);
297	  mbedtls_ssl_config_free(&c->conf);
298	  mbedtls_ctr_drbg_free(&c->ctr_drbg);
299	  mbedtls_entropy_free(&c->entropy);
300	
301	  if (c->fd >= 0)
302	    {
303	      close(c->fd);
304	    }
305	
306	  free(c);
307	  return 0;
308	}
309	
310	static int xz_tls_get_poll_info(FAR void *ctx,
311	                                 FAR struct webclient_tls_connection *conn,
312	                                 FAR struct webclient_poll_info *info)
313	{
314	  struct xz_tls_conn_s *c = (struct xz_tls_conn_s *)conn;
315	  (void)ctx;
316	
317	  info->fd = c->fd;
318	  info->flags = 0;
319	  return 0;
320	}
321	
322	/****************************************************************************
323	 * Public Data
324	 ****************************************************************************/
325	
326	/* The TLS ops vector plugged into webclient_context.tls_ops by the OTA
327	 * caller. init_connection is left NULL (we don't tunnel through an http
328	 * proxy); webclient only needs it for https-over-proxy, which we never use.
329	 */
330	const struct webclient_tls_ops g_xz_tls_ops =
331	{
332	  .connect        = xz_tls_connect,
333	  .send           = xz_tls_send,
334	  .recv           = xz_tls_recv,
335	  .close          = xz_tls_close,
336	  .get_poll_info  = xz_tls_get_poll_info,
337	  .init_connection = NULL,
338	};
