75	int mcp_server_handle_message(const cJSON *msg,
76	                              int (*send_json_cb)(cJSON *))
77	{
78	  if (msg == NULL || send_json_cb == NULL)
79	    {
80	      return -1;
81	    }
82	
83	  /* Server sends: {"type":"mcp","payload":{...},"session_id":"..."} */
84	
85	  cJSON *payload = cJSON_GetObjectItem(msg, "payload");
86	  if (!cJSON_IsObject(payload))
87	    {
88	      printf("[mcp] mcp message has no payload\n");
89	      return -1;
90	    }
91	
92	  /* Handle JSON-RPC method dispatch inside payload. */
93	
94	  cJSON *method = cJSON_GetObjectItem(payload, "method");
95	  cJSON *id_item = cJSON_GetObjectItem(payload, "id");
96	
97	  if (cJSON_IsString(method))
98	    {
99	      const char *method_name = method->valuestring;
100	      printf("[mcp] method: %s\n", method_name);
101	
102	      if (strcmp(method_name, "initialize") == 0)
103	        {
104	          /* Respond with server capabilities (JSON-RPC result). */
105	
106	          cJSON *resp = cJSON_CreateObject();
107	          cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
108	          if (id_item != NULL)
109	            {
110	              cJSON_AddItemReferenceToObject(resp, "id", id_item);
111	            }
112	
113	          cJSON *result = cJSON_CreateObject();
114	          cJSON_AddStringToObject(result, "protocolVersion", "2024-11-05");
115	
116	          cJSON *caps = cJSON_CreateObject();
117	          cJSON *tools_caps = cJSON_CreateObject();
118	          cJSON_AddBoolToObject(tools_caps, "listChanged", false);
119	          cJSON_AddItemToObject(caps, "tools", tools_caps);
120	          cJSON_AddItemToObject(result, "capabilities", caps);
121	
122	          cJSON *server_info = cJSON_CreateObject();
123	          cJSON_AddStringToObject(server_info, "name", "xiaozhi-device");
124	          cJSON_AddStringToObject(server_info, "version", "1.0.0");
125	          cJSON_AddItemToObject(result, "serverInfo", server_info);
126	
127	          cJSON_AddItemToObject(resp, "result", result);
128	
129	          printf("[mcp] sending initialize response\n");
130	          int ret = send_json_cb(resp);
131	          cJSON_Delete(resp);
132	          return ret;
133	        }
134	      else if (strcmp(method_name, "notifications/tools/list_changed") == 0)
135	        {
136	          printf("[mcp] tools list changed notification, ignored\n");
137	          return 0;
138	        }
139	    }
140	
141	  /* Handle tool_calls — may be at top level or inside payload. */
142	
143	  cJSON *tool_calls = cJSON_GetObjectItem(msg, "tool_calls");
144	  if (!cJSON_IsArray(tool_calls))
145	    {
146	      tool_calls = cJSON_GetObjectItem(payload, "tool_calls");
147	    }
148	
149	  if (!cJSON_IsArray(tool_calls))
150	    {
151	      printf("[mcp] no tool_calls in message\n");
152	      return -1;
153	    }
154	
155	  int n_calls = cJSON_GetArraySize(tool_calls);
156	  int i;
157	
158	  for (i = 0; i < n_calls; i++)
159	    {
160	      cJSON *call = cJSON_GetArrayItem(tool_calls, i);
161	      if (!cJSON_IsObject(call))
162	        {
163	          continue;
164	        }
165	
166	      cJSON *call_id_item = cJSON_GetObjectItem(call, "id");
167	      cJSON *name_item = cJSON_GetObjectItem(call, "name");
168	      cJSON *args_item = cJSON_GetObjectItem(call, "arguments");
169	
170	      const char *call_id = cJSON_IsString(call_id_item) ?
171	                            call_id_item->valuestring : "";
172	      const char *tool_name = cJSON_IsString(name_item) ?
173	                              name_item->valuestring : "";
174	
175	      printf("[mcp] tool_call: id=%s name=%s\n", call_id, tool_name);
176	
177	      struct mcp_tool_s *tool = find_tool(tool_name);
178	      cJSON *result = NULL;
179	
180	      if (tool != NULL)
181	        {
182	          printf("[mcp] executing tool: %s\n", tool_name);
183	          result = tool->callback(args_item);
184	        }
185	      else
186	        {
187	          printf("[mcp] unknown tool: %s\n", tool_name);
188	          result = cJSON_CreateString("error: unknown tool");
189	        }
190	
191	      /* Build tool_results response. */
192	
193	      cJSON *resp = cJSON_CreateObject();
194	      cJSON_AddStringToObject(resp, "type", "mcp");
195	
196	      cJSON *results = cJSON_CreateArray();
197	      cJSON *entry = cJSON_CreateObject();
198	      cJSON_AddStringToObject(entry, "id", call_id);
199	
200	      if (result != NULL)
201	        {
202	          cJSON_AddItemToObject(entry, "result", result);
203	        }
204	      else
205	        {
206	          cJSON_AddStringToObject(entry, "result", "null");
207	        }
208	
209	      cJSON_AddItemToArray(results, entry);
210	      cJSON_AddItemToObject(resp, "tool_results", results);
211	
212	      int ret = send_json_cb(resp);
213	      cJSON_Delete(resp);
214	
215	      if (ret != 0)
216	        {
217	          printf("[mcp] failed to send tool_result for %s\n", tool_name);
218	        }
219	    }
220	
221	  return 0;
222	}
