static int mcp_send_json(cJSON *msg)
{
  if (s_mcp_app == NULL)
    {
      return -1;
    }

  /* Wrap in transport format if not already wrapped. */

  cJSON *type = cJSON_GetObjectItem(msg, "type");
  if (type == NULL)
    {
      cJSON *wrapper = cJSON_CreateObject();
      cJSON_AddStringToObject(wrapper, "type", "mcp");
      cJSON_AddItemToObject(wrapper, "payload", cJSON_DetachItemFromObject(msg, "payload"));

