898	    if (model->long_pressed) {
899	        for (int i = 0; i < MAX_ALARM_COUNT; i++) {
900	            if(alarm_view.alarm_containers[i] != NULL){
901	                lv_obj_add_flag(alarm_view.alarm_switches[i], LV_OBJ_FLAG_HIDDEN);
