909	            lv_obj_remove_flag(alarm_view.del_sel_btn, LV_OBJ_FLAG_CLICKABLE);
910	            lv_obj_set_style_bg_color(alarm_view.del_sel_btn, lv_color_make(36, 32, 35), LV_PART_MAIN);
